const records = [3, 12, 3, 10, 5, 29];
const kept = records.filter((value) => value < 24);
let max = Math.max(...kept);
const edges = { 10: [12], 12: [] };

// Check if there is a path from max to 10
function hasPath(start, end, graph) {
  const visited = new Set();
  const queue = [start];

  while (queue.length > 0) {
    const current = queue.shift();
    if (current === end) return true;
    if (visited.has(current)) continue;
    visited.add(current);
    for (const neighbor of graph[current]) {
      if (!visited.has(neighbor)) {
        queue.push(neighbor);
      }
    }
  }
  return false;
}

const pathExists = hasPath(max, 10, edges);
return pathExists ? "Yes" : "No";
```

